export const PRICES = {
  heal: 60,
  armor: 120,
  pistol: 250,
  ammoBox: 40,
  repairPerPoint: 1.2,
  bustFineRate: 0.25,
  wastedFee: 90,
};

// Neon signs and lit windows borrow from this palette after dark.
export const NEON = ['#ff2e88', '#22d3ee', '#facc15', '#a3e635', '#f97316', '#e879f9'];

export const SAVE_KEY = 'solstice-heat-neon-tide-save-v1';
